head.script:
///////// 1. 변수 및 선언 영역 /////////
// 원본 : ULDSTF05112.xml (W-Craft 변환본 + API 적용 개발 사본, 원본 ULDSTF05112.gfm 은 저장소에 없음)
/*
 * 화면 동작
 *  - 부모(ULDSTF05103·ULDSTF05104 종류주식 상장심사관리)가 넘긴 검색어(발행기관코드·명)와 증권그룹·시장구분으로
 *    종류주식 신규상장 대상 발행기관을 조회한다. 열리면 바로 조회하고, 발행기관명·코드로 다시 조회할 수 있다.
 *  - 행을 더블클릭하면 고른 법인을 부모에 돌려주고 닫는다(창 닫기 = 취소).
 * 업무 분석 : conversion/conversion-front/ui/ULDSTF05112/ULDSTF05112.md (§번호는 이 문서의 절)
 */

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 29
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다. (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05112.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 29
 * @description 로딩 — 파라미터 수신(검색어 초기값·조회 조건) → Enter 키 바인딩 → 신규상장 발행기관 목록 조회. (원본 scwin.init — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 파라미터 수신 — 원본의 부모 fn_GetPar 호환 분기는 지우고 data 만 받는다 (§1.2)
    //    부모 검색 칸의 코드·명을 검색어 초기값으로 쓴다(원본 strSch 초기 검색 의도 — §8 #3). searchType 은 API 가 받지 않는다 (§10 #1)
    const param = $c.data.getParameter() ?? {};
    dma_listReq.set("isurCd", param.isurCd ?? "");
    dma_listReq.set("comNm", param.isurNm ?? "");
    dma_listReq.set("secugrpId", param.secugrpId ?? "");
    dma_listReq.set("spotIsuTrdMktTpCd", param.mktTpCd ?? "");

    // 2) 조회 영역 Enter 키 (규칙 22)
    $c.win.setEnterKeyEvent(grp_search, scwin.img_Search_onclick);

    // 3) 열리면 바로 조회
    await scwin.selectList();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.img_Search_onclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description [조회] — 발행기관명·코드로 다시 조회한다. (원본 img_Search_onclick — §4)
 * @returns
 * @hidden N
 */
scwin.img_Search_onclick = async function () {
    try {
        await scwin.selectList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05112.img_Search_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_IsuInst_oncelldblclick
 * @author Inswave
 * @date 2026. 10. 29
 * @description 목록 더블클릭 — 고른 법인을 부모에 돌려주고 닫는다. (원본 grd_IsuInst_OnDblClick — §4)
 * @param {Number} rowIndex 행 번호
 * @param {Number} columnIndex 열 번호
 * @param {String} columnId 열 id
 * @returns
 * @hidden N
 */
scwin.grd_IsuInst_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
    try {
        await scwin.returnIsur(rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05112.grd_IsuInst_oncelldblclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 29
 * @description 신규상장 발행기관 목록 조회 — GET select-list-newlisting-kindstk(isurCd·comNm·secugrpId·spotIsuTrdMktTpCd) → dlt_listRes, 건수 표시.
 * (원본 fn_list_sync + dts_IsurInst_OnLoadCompleted — §5.1)
 * @returns
 * @hidden N
 */
scwin.selectList = async function () {
    const sbmOptions = {
        id : "sbm_selectListNewlistingKindstk",
        action : "/api/listing/common/pop/issur/select-list-newlisting-kindstk",
        method : "get",
        ref : "dma_listReq",
        target : "dlt_listRes=body",
        isProcessMsg : false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res?.skipped) return;   // 진행 중 조회가 있어 이번 호출은 건너뜀

    txb_TotCnt.setValue(dlt_listRes.getRowCount());
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.returnIsur
 * @author Inswave
 * @date 2026. 10. 29
 * @description 고른 법인을 반환 계약 키(camelCase)로 부모에 돌려주고 닫는다. 원본의 대문자 키(ISUR_CD 등)와 getRowPosition 기준 읽기는 쓰지 않는다. (§1.2 반환 규약)
 * @param {Number} rowIndex 행 번호
 * @returns
 * @hidden N
 */
scwin.returnIsur = async function (rowIndex) {
    const row = dlt_listRes.getRowJSON(rowIndex);

    await $c.win.closePopup({
        isurCd : row.isurCd ?? "",                              // AS-IS ISUR_CD
        comNm : row.comNm ?? "",                                // AS-IS COM_NM
        listDd : row.listDd ?? "",                              // AS-IS LIST_DD
        prelmInvstgBzProcsNo : row.prelmInvstgBzProcsNo ?? "",  // AS-IS PRELM_INVSTG_BZ_PROCS_NO
        dbClickYn : "Y"                                         // AS-IS DBCLICKYN
    });
};
